# Generated by build.py from recipe.yml for recipe http-keep-files-across-restarts. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'uploaded before this surl started' > site/kept.txt
printf '%s\n' 'uploaded by curl' > notes.txt
surl --directory site --allow-uploads --user alice:s3cret http://127.0.0.1:8080/ &
sleep 1
curl --digest -u alice:s3cret -T notes.txt http://127.0.0.1:8080/notes.txt
kill $(jobs -p)
